// Generate inc/icons.php: the Lucide icons the theme uses, as PHP strings, so
// every pictogram on the site comes from one set on one 24px grid with one
// stroke weight (13 Oct 2026; the hand-drawn icons were all slightly different).
//
// Source: lucide-react in the repo's node_modules (ISC licence; the notice is
// copied into the generated file). Add a name to ICONS and re-run:
//   node restwell-theme/tools/build-icons.mjs
import fs from 'node:fs';
import path from 'node:path';

const THEME = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const LUCIDE = path.resolve(THEME, '../node_modules/lucide-react');

const ICONS = [
	// Home key facts.
	'house', 'car-front', 'shower-head', 'bed',
	// Getting around (Whitstable guide).
	'train-front', 'bus-front', 'car-taxi-front',
	// What we send (Funding).
	'receipt-text', 'clipboard-list', 'files',
	// Care support types (Optional care).
	'hand-heart', 'clock', 'moon', 'move-vertical',
	// Audiences (Who It's For).
	'users', 'clipboard-check', 'building-2',
	// Parking (Whitstable guide).
	'square-parking', 'badge-check',
	// Notices, forms and controls.
	'info', 'triangle-alert', 'check', 'circle-check', 'plus', 'minus',
	'arrow-right', 'arrow-up-right', 'arrow-up', 'x', 'chevron-left', 'chevron-right', 'chevron-down',
	'phone', 'mail', 'map-pin',
	// Accessibility: spec register and the access statement download.
	'file-text', 'download',
];

const pkg = JSON.parse(fs.readFileSync(path.join(LUCIDE, 'package.json'), 'utf8'));
const licence = fs.readFileSync(path.join(LUCIDE, 'LICENSE'), 'utf8').trim();

const attrRe = /(\w+):\s*(?:"([^"]*)"|([\d.]+))/g;
const nodeRe = /\[\s*"(\w+)",\s*\{([^}]*)\}\s*\]/g;

const entries = ICONS.map((name) => {
	const file = path.join(LUCIDE, 'dist/esm/icons', name + '.js');
	if (!fs.existsSync(file)) {
		throw new Error('No Lucide icon named ' + name);
	}
	const src = fs.readFileSync(file, 'utf8');
	const body = src.slice(src.indexOf('createLucideIcon('));
	let markup = '';
	for (const [, tag, attrs] of body.matchAll(nodeRe)) {
		let out = '';
		for (const [, key, str, num] of attrs.matchAll(attrRe)) {
			if (key === 'key') continue;
			out += ` ${key}="${str ?? num}"`;
		}
		markup += `<${tag}${out}/>`;
	}
	if (!markup) {
		throw new Error('Could not read the paths for ' + name);
	}
	return `\t\t'${name}' => '${markup}',`;
});

const php = `<?php
/**
 * Icons: a subset of Lucide v${pkg.version} (https://lucide.dev), generated by
 * tools/build-icons.mjs. Do not edit by hand; add the name there and re-run.
 *
 * ${licence.split('\n').join('\n * ').replace(/ \* $/gm, ' *')}
 *
 * @package Restwell_Retreats
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Inner SVG markup for each icon, keyed by Lucide name.
 *
 * @return array<string, string>
 */
function restwell_icon_paths() {
	return array(
${entries.join('\n')}
	);
}

/**
 * An icon as an inline SVG: decorative, so hidden from assistive technology.
 * Strokes use currentColor; size it with CSS (the .icon class is 1.5rem).
 *
 * @param string $name  Lucide icon name.
 * @param string $class Extra classes.
 * @return string SVG markup, or '' for an unknown name.
 */
function restwell_icon( $name, $class = '' ) {
	$paths = restwell_icon_paths();
	if ( ! isset( $paths[ $name ] ) ) {
		return '';
	}
	$classes = trim( 'icon icon--' . $name . ' ' . $class );
	return '<svg class="' . esc_attr( $classes ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $paths[ $name ] . '</svg>';
}

/**
 * Echo an icon (see restwell_icon()).
 *
 * @param string $name  Lucide icon name.
 * @param string $class Extra classes.
 */
function restwell_the_icon( $name, $class = '' ) {
	echo restwell_icon( $name, $class ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- static SVG paths from the generated table; the class is escaped.
}
`;

fs.writeFileSync(path.join(THEME, 'inc/icons.php'), php);
console.log('inc/icons.php:', ICONS.length, 'icons from Lucide', pkg.version);
